cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && python3 - <<'EOF'
import subprocess, re
repo="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
def run(*a):
    return subprocess.run(a,cwd=repo,capture_output=True,text=True).stdout
files=[f for f in run("git","ls-tree","-r","--name-only","origin/main").split() if re.match(r"S\d+/E\d+\.md$",f)]
filed={}
for e in files:
    for sha in re.findall(r"Source: friend/\w+ @ ([0-9a-f]{40})", run("git","show",f"origin/main:{e}")):
        filed[sha]=e
print("filed:",len(filed))
missing=[]
for b in ["rachel","monica","phoebe","joey","chandler","ross"]:
    out=run("git","log","--format=%H%x00%B%x01",f"origin/friend/{b}")
    for rec in out.split("\x01"):
        rec=rec.strip("\n")
        if not rec.strip(): continue
        sha,body=rec.split("\x00",1)
        sha=sha.strip()
        if "Friend-Message: 1" in body:
            m=re.search(r"^Episode: (\S+)",body,re.M)
            ep=m.group(1) if m else "?"
            if sha not in filed:
                missing.append((b,ep,sha,body.strip().splitlines()[0]))
print("missing:",len(missing))
for x in missing: print(x[0],x[1],x[2],x[3][:60])
EOF
